style.css:
/* Midnight Geometry — ihavenotv.com */

:root {
  /* swap these colors to customize */
  --my-bg: #10131d;
  --my-dot: rgba(120, 155, 220, 0.16);
}

/* patterned background */
html,
body {
  background-color: var(--my-bg) !important;
  background-image:
    radial-gradient(
      circle,
      var(--my-dot) 1.2px,
      transparent 1.5px
    ) !important;
  background-size: 26px 26px !important;
  background-attachment: fixed !important;
}

/* subtle background depth */
body {
  background-image:
    radial-gradient(
      circle,
      var(--my-dot) 1.2px,
      transparent 1.5px
    ),
    radial-gradient(
      ellipse at 50% 0%,
      rgba(55, 90, 155, 0.13),
      transparent 65%
    ) !important;
  background-size: 26px 26px, 100% 100% !important;
  background-attachment: fixed !important;
}
